287	<script>
288	(function(){
289	var $=function(i){return document.getElementById(i)};
290	var AG=[
291	 "Open Claude Code in any folder, then paste this.",
292	 "Open the Cursor agent chat with terminal access, then paste this.",
293	 "Start Codex in any folder, then paste this."];
294	var cur=0,txt="",idx=[];
295	/* cached runs: examples/index.json, read once, ignored if missing */
296	var ready=fetch("examples/index.json").then(function(r){return r.ok?r.json():{}}).then(function(j){idx=(j&&j.runs&&j.runs.length)?j.runs:[]}).catch(function(){idx=[]});
297	function clean(s){return String(s).replace(/[\u0000-\u001f\u007f]+/g," ").replace(/\s+/g," ").trim().slice(0,300)}
298	function norm(raw){
299	 var s=clean(raw);
300	 if(!s)return null;
301	 if(/^https?:\/\/\S+$/i.test(s))return{url:s};
302	 if(/^[a-z0-9-]+(\.[a-z0-9-]+)+(:\d+)?([\/?#]\S*)?$/i.test(s))return{url:"https://"+s};
303	 return{url:"<URL>",q:s.replace(/"/g,"'")};
304	}
305	function key(s){
306	 s=String(s).trim().toLowerCase().replace(/^[a-z][a-z0-9+.-]*:\/\//,"").replace(/[?#].*$/,"");
307	 var i=s.indexOf("/"),h=i<0?s:s.slice(0,i),p=i<0?"":s.slice(i);
308	 return{h:h.replace(/^www\./,""),p:p.replace(/\/+$/,"")};
309	}
310	function lookup(raw){
311	 var s=clean(raw);
312	 if(!s||!idx.length)return null;
313	 var i,e,k,q;
314	 if(/[.\/]/.test(s)){
315	  q=key(s);
316	  for(i=0;i<idx.length;i++){k=key(idx[i].url||"");if(k.h===q.h&&k.p===q.p)return idx[i]}
317	  for(i=0;i<idx.length;i++){k=key(idx[i].url||"");if(k.h!==q.h)continue;
318	   if(q.p&&(k.p.indexOf(q.p+"/")===0||q.p.indexOf(k.p+"/")===0))return idx[i]}
319	  return null;
320	 }
321	 q=s.toLowerCase();
322	 for(i=0;i<idx.length;i++){e=String(idx[i].name||"").toLowerCase();if(e&&e===q)return idx[i]}
323	 if(q.length>=3)for(i=0;i<idx.length;i++){e=String(idx[i].name||"").toLowerCase();if(e&&e.indexOf(q)===0)return idx[i]}
324	 return null;
325	}
326	function fmtDate(d){
327	 var m=/^(\d{4})-(\d{2})-(\d{2})/.exec(d||"");
328	 if(!m)return d||"";
329	 return["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+m[2]-1]+" "+(+m[3])+", "+m[1];
330	}
331	function paintHit(h){
332	 var on=!!h;
333	 $("hit").hidden=!on;$("fresh").hidden=!on;
334	 if(!on)return;
335	 var st=String(h.status||"verified"),f=+h.fixes||0,bits=[];
336	 $("hit-p").textContent=st.charAt(0).toUpperCase()+st.slice(1);
337	 $("hit-p").className="pill"+(st==="verified"?"":" other");
338	 if(h.date)bits.push(fmtDate(h.date));
339	 bits.push(f?f+(f===1?" fix":" fixes"):"No fixes needed");
340	 $("hit-m").textContent=bits.join(" · ");
341	 $("hit-t").textContent=h.title||h.name||h.url;
342	 $("hit-s").textContent=h.summary||"";
343	 $("hit-a").href="run.html#ex="+encodeURIComponent(h.example||h.name||"");
344	}
345	function build(r){
346	 var u=r.url,L=[];
347	 if(r.q){
348	  L.push('Goal: test the quickstart for "'+r.q+'" the way a new developer would, fix any step that breaks, and prove the fix.');
349	  L.push('');
350	  L.push('0. "'+r.q+'" is not a URL. Find the official quickstart page for it, show me the URL, and use it as <URL> below.');
351	 }else{
352	  L.push("Goal: test the quickstart at "+u+" the way a new developer would, fix any step that breaks, and prove the fix.");
353	  L.push('');
354	 }
355	 L.push("1. Run `docker info`. If it fails, tell me what is missing and how to fix it. On Windows, use Docker inside WSL and set FIRSTRUN_DOCKER. Stop until it works.");
356	 L.push("2. Run `pip install git+https://github.com/HighnessAtharva/firstrun`.");
357	 L.push("3. Check that CLAUDE_CODE_OAUTH_TOKEN is set. If not, ask me to run `claude setup-token` and set it. Never print a secret.");
358	 L.push("4. Run `firstrun "+u+"`. While it runs, tell me in plain words which repo it uses and which step it is on.");
359	 L.push("5. Read runs/<id>/report.md. Tell me in 3 to 6 short sentences: which step broke, the error, the class Jev gave it, the fix, and whether a fresh container verified the fix.");
360	 L.push("6. If the fix is verified and patches the docs, show me the diff and the PR body. Ask \"Open this PR on <repo>?\" and wait for my yes. Open nothing before that.");
361	 L.push("7. After a yes, run `firstrun pr <id> --json` and run the gh commands it prints.");
362	 L.push("8. Last, print the line that starts with \"share:\" from the run output, so I can watch the replay.");
363	 return L.join("\n");
364	}
365	function render(){
366	 $("pre").textContent=txt;
367	 $("how").textContent=AG[cur];
368	 for(var i=0;i<3;i++){var t=$("t"+i);t.setAttribute("aria-selected",i===cur?"true":"false");t.tabIndex=i===cur?0:-1}
369	 $("pre").setAttribute("aria-labelledby","t"+cur);
370	}
371	function show(){
372	 var raw=$("u").value,r=norm(raw);
373	 if(!r){$("u").focus();return}
374	 txt=build(r);
375	 Promise.race([ready,new Promise(function(ok){setTimeout(ok,500)})]).then(function(){
376	  paintHit(lookup(raw));
377	  $("out").hidden=false;
378	  render();
379	  $("out").scrollIntoView({behavior:matchMedia("(prefers-reduced-motion:reduce)").matches?"auto":"smooth",block:"start"});
380	 });
381	}
382	/* live hint: say so as soon as a typed URL or name has a saved run */
383	function hintNow(){
384	 var h=lookup($("u").value),el=$("hint");
385	 if(h){el.textContent="Saved run found: "+(h.title||h.name)+". Press Enter to watch it.";el.className="hint cached"}
386	 else{el.textContent=el.getAttribute("data-d");el.className="hint"}
387	}
388	$("u").addEventListener("input",hintNow);
389	$("u").addEventListener("paste",function(){setTimeout(hintNow,0)});
390	$("f").addEventListener("submit",function(e){e.preventDefault();show()});
391	$("chips").addEventListener("click",function(e){var u=e.target.getAttribute&&e.target.getAttribute("data-u");if(u){$("u").value=u;hintNow();show()}});
392	var tb=document.querySelector(".tabs");
393	tb.addEventListener("click",function(e){var i=e.target.getAttribute&&e.target.getAttribute("data-i");if(i!==null&&i!==undefined){cur=+i;render()}});
394	tb.addEventListener("keydown",function(e){
395	 if(e.key==="ArrowRight"||e.key==="ArrowLeft"){cur=(cur+(e.key==="ArrowRight"?1:2))%3;render();$("t"+cur).focus()}});
396	$("cp").addEventListener("click",function(){
397	 var b=this;
398	 (navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(function(){b.textContent="Copied"},function(){
399	  var r=document.createRange();r.selectNodeContents($("pre"));var s=getSelection();s.removeAllRanges();s.addRange(r);b.textContent="Press Ctrl+C"});
400	 setTimeout(function(){b.textContent="Copy prompt"},2000)});
401	Array.prototype.forEach.call(document.querySelectorAll("#ex a[data-n]"),function(el){
402	 fetch("examples/"+el.getAttribute("data-n")+".txt",{method:"HEAD"}).then(function(r){el.hidden=!r.ok}).catch(function(){el.hidden=true});
403	});
404	/* X embeds: load the widget script only when the timeline nears the viewport */
405	var tl=$("built"),loaded=false;
406	function loadX(){
407	 if(loaded)return;loaded=true;
408	 var s=document.createElement("script");s.async=true;s.src="https://platform.twitter.com/widgets.js";s.charset="utf-8";
409	 document.body.appendChild(s);
410	}
411	if("IntersectionObserver" in window){
412	 var io=new IntersectionObserver(function(en){if(en[0].isIntersecting){io.disconnect();loadX()}},{rootMargin:"400px 0px"});
413	 io.observe(tl);
414	}else{loadX()}
415	})();
416	</script>
417	</body>
