input.content:
:root{--page:#F5F5F7;--surface:#FBFBFD;--ink:#1D1D1F;--muted:#6E6E73;--accent:#0066CC;--accent-d:#0058b0;--tint:#E8F1FB;--pass:#1F8A3B;--hair:rgba(29,29,31,.08);--road:#E3E3E8;--ease:cubic-bezier(.16,1,.3,1);--shadow:0 1px 3px rgba(0,0,0,.04),0 6px 24px rgba(0,0,0,.06);--pad:clamp(48px,6.5vw,76px)}
*{box-sizing:border-box;margin:0}
html{background:var(--page);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%;scroll-behavior:smooth;scroll-padding-top:56px}
body{line-height:1.45;font-size:17px;overflow-x:hidden;-webkit-font-smoothing:antialiased}
code,pre,.mono{font-family:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
a{color:var(--accent);text-underline-offset:3px}
a:focus-visible,button:focus-visible,input:focus-visible,[role=tab]:focus-visible,pre:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:10px}
section{max-width:960px;margin:0 auto;padding:var(--pad) 24px}
h1{font-size:clamp(38px,7.2vw,76px);line-height:1.03;letter-spacing:-.045em;font-weight:700}
h2{font-size:clamp(26px,4vw,40px);line-height:1.08;letter-spacing:-.035em;font-weight:700;margin-bottom:12px}
.lede{font-size:clamp(17px,2vw,21px);color:var(--muted);max-width:31em;margin-top:14px;line-height:1.4}
.eyebrow{font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);font-weight:600;margin-bottom:10px}
/* motion: reveal on scroll, only when JS runs */
html.js .rv{opacity:0;transform:translateY(18px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
html.js .rv.in{opacity:1;transform:none}
@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
/* nav */
.nav{position:sticky;top:0;z-index:20;height:48px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 max(20px,calc((100vw - 1040px)/2));background:rgba(245,245,247,.82);-webkit-backdrop-filter:saturate(180%) blur(20px);backdrop-filter:saturate(180%) blur(20px);box-shadow:0 .5px 0 var(--hair)}
.wm{font-weight:700;font-size:15px;color:var(--ink);text-decoration:none;letter-spacing:-.01em}
.wm i{display:inline-block;width:.5em;height:.95em;background:var(--accent);vertical-align:-.12em;margin-left:3px}
.nl{display:flex;gap:26px;font-size:13px}
.nl a{color:var(--muted);text-decoration:none;transition:color .2s}
.nl a:hover{color:var(--ink)}
.nav .sm{min-height:30px;padding:4px 14px;font-size:13px;border-radius:99px}
/* hero */
#hero{padding-top:clamp(36px,6vw,64px);padding-bottom:clamp(20px,3vw,32px);text-align:center}
#hero>*{animation:rise .7s var(--ease) both}
#hero>:nth-child(2){animation-delay:.06s}#hero>:nth-child(3){animation-delay:.12s}#hero>:nth-child(4){animation-delay:.18s}
#hero .lede{margin-left:auto;margin-right:auto}
.box{display:flex;gap:8px;align-items:center;margin:28px auto 0;max-width:640px;background:var(--surface);border-radius:20px;padding:7px 7px 7px 20px;box-shadow:var(--shadow);transition:box-shadow .25s var(--ease)}
.box:focus-within{box-shadow:0 0 0 3px var(--accent),var(--shadow)}
.box input{flex:1;min-width:0;font:inherit;font-size:18px;border:0;background:none;color:var(--ink);padding:10px 0;outline:0}
.box input::placeholder{color:#76767c}
button,.btn{font:inherit;font-weight:600;font-size:15px;background:var(--accent);color:#fff;border:0;border-radius:14px;padding:10px 20px;cursor:pointer;min-height:44px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;transition:background .2s,transform .2s var(--ease)}
button:hover,.btn:hover{background:var(--accent-d)}
button:active,.btn:active{transform:scale(.97)}
.chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:14px}
.chips button{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--hair);border-radius:99px;font-weight:500;font-size:14px;padding:4px 14px;min-height:36px}
.chips button:hover{background:var(--tint);box-shadow:inset 0 0 0 1px var(--accent);color:var(--accent)}
.chips .lbl{color:var(--muted);font-size:14px;align-self:center}
.hint{color:var(--muted);font-size:14px;margin-top:10px;min-height:1.45em}
.hint.cached{color:var(--pass);font-weight:500}
#out{padding-top:8px;padding-bottom:var(--pad)}
.hit{background:var(--surface);border-radius:24px;box-shadow:var(--shadow);padding:24px 26px;margin-bottom:22px}
.hit[hidden],.fresh[hidden]{display:none}
.hit-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;color:var(--muted);font-size:14px}
.pill{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:13px;border-radius:99px;padding:3px 11px;background:#EAF5EC;color:var(--pass)}
.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.pill.other{background:var(--tint);color:var(--accent)}
.hit h3{font-size:clamp(22px,3.2vw,30px);letter-spacing:-.03em;line-height:1.15;margin-top:12px}
.hit p{color:var(--muted);margin-top:6px;max-width:38em}
.hit-act{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin-top:18px}
.hit-act span{color:var(--muted);font-size:14px}
.fresh{font-size:16px;letter-spacing:-.01em;color:var(--muted);font-weight:600;margin:0 0 10px 4px}
.panel{background:var(--surface);border-radius:24px;box-shadow:var(--shadow);overflow:hidden}
.tabs{display:flex;gap:2px;padding:8px 8px 0;box-shadow:0 1px 0 var(--hair);align-items:flex-end}
.tabs [role=tab]{font:inherit;font-size:14px;font-weight:600;color:var(--muted);background:none;border:0;border-radius:10px 10px 0 0;padding:8px 14px;min-height:42px;cursor:pointer}
.tabs [role=tab]:hover{background:none;color:var(--ink)}
.tabs [role=tab][aria-selected=true]{color:var(--accent);box-shadow:inset 0 -2px 0 var(--accent)}
.tabs .sp{flex:1}
.tabs .cp{margin:0 4px 6px 0;padding:6px 16px;min-height:36px;font-size:14px;border-radius:99px}
.tabs .cp:hover{background:var(--accent-d)}
.how{padding:12px 20px 0;color:var(--muted);font-size:14px}
pre{white-space:pre-wrap;word-break:break-word;font-size:14px;line-height:1.6;padding:10px 20px 20px;max-height:420px;overflow:auto;color:var(--ink)}
.strip{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px 16px;margin-top:20px;counter-reset:s}
.strip li{counter-increment:s;font-size:15px;color:var(--ink);line-height:1.35}
.strip li:before{content:counter(s);display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:12px;color:var(--accent);font-weight:600;margin-bottom:3px}
.strip li span{color:var(--muted)}
/* film: full bleed, no frame, edges melt into the page */
#film{max-width:none;padding:var(--pad) 0 clamp(24px,4vw,44px)}
.film .wrap{max-width:960px;margin:0 auto;padding:0 24px;text-align:center}
.film .lede{margin-left:auto;margin-right:auto}
.reel{position:relative;max-width:1680px;margin:clamp(8px,2vw,20px) auto 0;aspect-ratio:2/1}
.reel video{display:block;width:100%;height:100%;object-fit:cover;background:#F3F3F5;border:0;border-radius:0;box-shadow:none;outline:0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 10%,#000 90%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 10%,#000 90%,transparent);mask-composite:intersect}
.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}
.ctl button{min-height:34px;padding:4px 14px;font-size:13px;border-radius:99px;background:rgba(29,29,31,.74);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.ctl button:hover{background:rgba(29,29,31,.92)}
.cap{color:var(--muted);font-size:14px;margin-top:6px}
/* how */
.rrp{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(20px,3.5vw,36px);margin-top:28px}
.rrp figure{background:#ECECF0;border-radius:18px;overflow:hidden;aspect-ratio:16/10;display:flex;align-items:center;justify-content:center}
.rrp img{width:100%;height:100%;object-fit:contain;display:block}
.rrp h3{font-size:24px;letter-spacing:-.03em;margin-top:14px}
.rrp p{color:var(--muted);font-size:15px;margin-top:4px}
/* watch */
.watch{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.watch a{display:inline-block;text-decoration:none;color:var(--ink);background:var(--surface);border-radius:16px;padding:12px 18px;box-shadow:var(--shadow);font-weight:600;transition:transform .25s var(--ease),color .2s}
.watch a[hidden]{display:none}
.watch a small{display:block;font-weight:400;color:var(--muted);font-size:13px}
.watch a:hover{color:var(--accent);transform:translateY(-2px)}
.cli{background:var(--surface);border-radius:16px;box-shadow:var(--shadow);padding:16px 20px;margin-top:14px;font-size:14px;line-height:1.8;overflow-x:auto;white-space:pre}
.cli .p,.cli .c{color:var(--muted)}
.cli .p{user-select:none}
/* tools */
.band{background:var(--surface)}
.tools{display:grid;gap:12px;margin-top:28px}
.tool{background:var(--page);border-radius:26px;padding:clamp(20px,3vw,28px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:clamp(20px,3.5vw,32px);align-items:center}
.tool:nth-child(even) .txt{order:2}
.tool header{display:flex;align-items:center;gap:10px}
.tool img.lg{width:38px;height:38px;border-radius:10px;display:block}
.tool h3{font-size:20px;letter-spacing:-.025em}
.tool .job{font-size:clamp(22px,2.8vw,28px);font-weight:700;letter-spacing:-.03em;line-height:1.15;margin-top:16px}
.tool p{color:var(--muted);font-size:15px;margin-top:6px}
.tool figure{border-radius:14px;overflow:hidden;background:#fff;box-shadow:var(--shadow)}
.tool figure img{display:block;width:100%;height:auto}
.tool figcaption{font-size:13px;color:var(--muted);padding:8px 14px;background:var(--surface);box-shadow:0 -1px 0 var(--hair)}
.tool .more{display:inline-block;margin-top:12px;font-size:14px;font-weight:600}
/* results */
.proof{margin-top:8px;color:var(--muted);max-width:36em}
/* timeline: a race track, two stops a row, hairpin turns at the edges */
#built{max-width:1120px}
.tlw{position:relative;margin-top:32px}
.trk{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.trk .road{fill:none;stroke:var(--road);stroke-width:16;stroke-linecap:round;stroke-linejoin:round}
.trk .mid{fill:none;stroke:#B4B4BC;stroke-width:2.5;stroke-dasharray:1 9;stroke-linecap:round}
.trk .done{fill:none;stroke:var(--accent);stroke-width:3;stroke-linecap:round}
.trk .done.anim{transition:stroke-dasharray 1.8s var(--ease)}
.trk .pt{fill:#fff;stroke:var(--accent);stroke-width:3}
.trk .pt.next{fill:var(--page);stroke:#9A9AA2}
.trk .ping{fill:none;stroke:var(--accent);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:ping 2.2s var(--ease) infinite}
@keyframes ping{from{transform:scale(1);opacity:.7}to{transform:scale(2.6);opacity:0}}
.tl{list-style:none;padding:0 clamp(36px,6vw,72px);margin:0;position:relative;z-index:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row dense;column-gap:clamp(20px,3.5vw,44px);row-gap:clamp(24px,3.5vw,40px)}
.tl li:nth-child(4n+3){grid-column:2}
.tl li:nth-child(4n+4){grid-column:1}
.tl li{padding-top:30px;min-width:0}
.tl .when b{display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:13px;color:var(--ink);font-weight:600}
.tl .when span{display:block;color:var(--muted);font-size:14px;margin-top:2px;line-height:1.35;margin-bottom:10px}
.twitter-tweet{background:var(--surface);border-radius:18px;padding:16px 18px;font-size:15px;line-height:1.5;max-width:550px;box-shadow:var(--shadow)}
.twitter-tweet p{margin:0 0 .5em}
.twitter-tweet a{word-break:break-word}
.twitter-tweet-rendered{margin:0!important}
.followx{font-weight:600;font-size:15px}
.tl li.next .when{margin-bottom:0}
/* about */
.about{display:grid;grid-template-columns:180px minmax(0,1fr);gap:clamp(24px,4vw,44px);align-items:center}
.about .ph{background:var(--tint);border-radius:26px;aspect-ratio:4/5;overflow:hidden}
.about .ph img{width:100%;height:100%;object-fit:cover;object-position:top;display:block}
.about p{color:var(--muted);margin-top:10px;max-width:34em}
.about p:first-of-type{margin-top:0}
.links{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.links a{text-decoration:none;color:var(--ink);background:var(--surface);box-shadow:var(--shadow);border-radius:99px;padding:6px 16px;font-weight:600;font-size:14px;min-height:36px;display:inline-flex;align-items:center;transition:color .2s}
.links a:hover{color:var(--accent)}
footer{max-width:960px;margin:0 auto;padding:28px 24px 48px;color:var(--muted);font-size:13px;display:flex;flex-wrap:wrap;gap:8px 24px;justify-content:space-between;box-shadow:0 -.5px 0 var(--hair)}
footer nav{display:flex;flex-wrap:wrap;gap:8px 20px}
@media(max-width:860px){.tool{grid-template-columns:1fr}.tool:nth-child(even) .txt{order:0}.rrp{grid-template-columns:1fr}.rrp figure{aspect-ratio:16/9}.nl{display:none}}
@media(max-width:720px){section{padding-left:20px;padding-right:20px}.strip{grid-template-columns:1fr 1fr}body{font-size:16px}.box{flex-wrap:wrap;padding:8px 8px 8px 16px;border-radius:20px}.box input{flex:1 1 100%;font-size:17px}.box button{width:100%}.tabs{flex-wrap:wrap}.tabs .sp{display:none}.tabs .cp{margin:0 0 6px auto}.hit{padding:20px}.hit-act .btn{width:100%}
 .reel{aspect-ratio:4/3}.ctl{right:20px;bottom:6%}
 .tl{grid-template-columns:minmax(0,1fr);padding:0 0 0 40px}.tl li:nth-child(n){grid-column:auto}
 .about{grid-template-columns:1fr;gap:20px}.about .ph{max-width:170px}}
@media(prefers-reduced-motion:reduce){#hero>*{animation:none}html.js .rv{opacity:1;transform:none;transition:none}.box,.trk .ping{transition:none;animation:none}html{scroll-behavior:auto}.trk .done.anim{transition:none}}

