:root{--page:#F4F5F9;--surface:#FBFBFD;--ink:#1D1D1F;--muted:#65656B;--accent:#0A66D6;--accent-d:#0856B5;--tint:#E6F0FC;--pass:#1B8A3A;--bad:#C4281C;--hair:rgba(29,29,31,.08);--road:rgba(29,29,31,.09);--ease:cubic-bezier(.16,1,.3,1);--pad:clamp(40px,5vw,60px);
--gl:linear-gradient(145deg,rgba(255,255,255,.78),rgba(255,255,255,.42));--gl-f:blur(24px) saturate(1.9);
--edge:inset 0 1.5px 0 rgba(255,255,255,.95),inset 0 -1px 0 rgba(255,255,255,.4),inset 0 0 0 1px rgba(255,255,255,.55),0 0 0 .5px rgba(20,30,60,.07);
--lift:0 1px 2px rgba(20,30,60,.05),0 12px 32px -8px rgba(30,50,110,.16),0 30px 70px -28px rgba(30,50,110,.18)}
*{box-sizing:border-box;margin:0}
html{background:var(--page);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%;scroll-behavior:smooth;scroll-padding-top:84px}
body{line-height:1.45;font-size:17px;overflow-x:hidden;-webkit-font-smoothing:antialiased;position:relative}
body:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(52vw 44vw at 10% 6%,rgba(10,122,255,.20),transparent 62%),radial-gradient(44vw 38vw at 92% 20%,rgba(168,108,255,.17),transparent 62%),radial-gradient(50vw 42vw at 72% 96%,rgba(36,200,168,.17),transparent 62%),radial-gradient(38vw 32vw at 4% 74%,rgba(255,158,92,.13),transparent 62%)}
code,pre,.mono{font-family:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
a{color:var(--accent);text-underline-offset:3px}
a:focus-visible,button:focus-visible,input:focus-visible,[role=tab]:focus-visible,pre:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:12px}
section{max-width:960px;margin:0 auto;padding:var(--pad) 24px}
h1{font-size:clamp(38px,7vw,74px);line-height:1.03;letter-spacing:-.045em;font-weight:700}
h2{font-size:clamp(26px,4vw,40px);line-height:1.08;letter-spacing:-.035em;font-weight:700;margin-bottom:12px}
.lede{font-size:clamp(17px,2vw,21px);color:var(--muted);max-width:31em;margin-top:12px;line-height:1.4}
/* liquid glass: translucent fill, bright top edge, soft lift, specular corner */
.gl,.hit,.panel,.tool,.cli,.watch a,.links a,.nav,.box,.chips button,.stk,.bdg,.twitter-tweet{background:var(--gl);-webkit-backdrop-filter:var(--gl-f);backdrop-filter:var(--gl-f);box-shadow:var(--edge),var(--lift)}
.hit,.panel,.tool,.box,.cli{position:relative}
.hit:before,.panel:before,.tool:before,.box:before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(90% 70% at 0% 0%,rgba(255,255,255,.7),transparent 52%)}
.hit>*,.panel>*,.tool>*,.box>*{position:relative}
/* motion */
html.js .rv{opacity:0;transform:translateY(20px) scale(.985);transition:opacity .9s var(--ease),transform .9s var(--ease)}
html.js .rv.in{opacity:1;transform:none}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes bob{0%,100%{transform:translateY(0) rotate(var(--r))}50%{transform:translateY(-9px) rotate(calc(var(--r) + 2.5deg))}}
@keyframes draw{0%,8%{stroke-dashoffset:var(--l)}30%,86%{stroke-dashoffset:0}100%{stroke-dashoffset:var(--l)}}
@keyframes spin{to{transform:rotate(360deg)}}
/* nav: floating glass pill */
.nav{position:sticky;top:12px;z-index:30;height:54px;width:min(980px,calc(100% - 24px));margin:12px auto 0;border-radius:99px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 9px 0 16px}
.wm{display:inline-flex;align-items:center;gap:9px;font-weight:700;font-size:16px;color:var(--ink);text-decoration:none;letter-spacing:-.025em}
.lg{width:28px;height:28px;display:block;filter:drop-shadow(0 3px 6px rgba(10,102,214,.35))}
.nl{display:flex;gap:4px;font-size:13.5px}
.nl a{color:var(--muted);text-decoration:none;padding:7px 13px;border-radius:99px;transition:color .2s,background .25s}
.nl a:hover{color:var(--ink);background:rgba(255,255,255,.65)}
.nav .sm{min-height:36px;padding:6px 18px;font-size:14px;border-radius:99px}
/* hero */
#hero{position:relative;padding-top:clamp(30px,5vw,56px);padding-bottom:clamp(18px,3vw,30px);text-align:center;max-width:1180px}
#hero>*{animation:rise .8s var(--ease) both}
#hero>:nth-child(2){animation-delay:.05s}#hero>:nth-child(3){animation-delay:.1s}#hero>:nth-child(4){animation-delay:.15s}#hero>:nth-child(5){animation-delay:.2s}
.icon{width:clamp(64px,8vw,84px);height:auto;margin:0 auto 22px;display:block;filter:drop-shadow(0 14px 22px rgba(10,102,214,.38));animation:rise .8s var(--ease) both,bob 7s ease-in-out 1s infinite;--r:0deg}
#hero .lede{margin-left:auto;margin-right:auto}
.box{display:flex;gap:8px;align-items:center;margin:26px auto 0;max-width:640px;border-radius:99px;padding:7px 7px 7px 24px;transition:box-shadow .3s var(--ease)}
.box:focus-within{box-shadow:var(--edge),0 0 0 3px var(--accent),var(--lift)}
.box input{flex:1;min-width:0;font:inherit;font-size:18px;border:0;background:none;color:var(--ink);padding:10px 0;outline:0}
.box input::placeholder{color:#76767c}
button,.btn{font:inherit;font-weight:600;font-size:15px;background:linear-gradient(180deg,#2B86F0,#0A66D6);color:#fff;border:0;border-radius:99px;padding:10px 22px;cursor:pointer;min-height:46px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;box-shadow:inset 0 1px 0 rgba(255,255,255,.45),0 6px 16px -4px rgba(10,102,214,.55);transition:filter .2s,transform .25s var(--ease)}
button:hover,.btn:hover{filter:brightness(1.07)}
button:active,.btn:active{transform:scale(.96)}
.chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:16px}
.chips button{background:var(--gl);color:var(--ink);border-radius:99px;font-weight:500;font-size:14px;padding:4px 16px;min-height:38px;box-shadow:var(--edge),0 4px 14px -6px rgba(30,50,110,.18)}
.chips button:hover{color:var(--accent);filter:none;transform:translateY(-2px)}
.chips .lbl{color:var(--muted);font-size:14px;align-self:center}
.hint{color:var(--muted);font-size:14px;margin-top:12px;min-height:1.45em}
.hint.cached{color:var(--pass);font-weight:500}
/* stickers */
.stk{position:absolute;z-index:2;display:none;align-items:center;gap:9px;padding:9px 16px 9px 11px;border-radius:99px;font:600 13px/1 "Geist Mono",ui-monospace,Consolas,monospace;animation:bob 7s ease-in-out infinite;pointer-events:none}
.stk svg{width:24px;height:24px;flex:none}
.stk.bad{color:var(--bad)}.stk.ok{color:var(--pass)}
.stk .d{stroke-dasharray:24;--l:24;animation:draw 5.5s ease-in-out infinite}
@media(min-width:1060px){.stk{display:inline-flex}}
#out{padding-top:8px;padding-bottom:var(--pad)}
.hit{border-radius:28px;padding:24px 26px;margin-bottom:20px}
.hit[hidden],.fresh[hidden]{display:none}
.hit-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;color:var(--muted);font-size:14px}
.pill{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:13px;border-radius:99px;padding:3px 11px;background:rgba(27,138,58,.12);color:var(--pass)}
.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.pill.other{background:var(--tint);color:var(--accent)}
.hit h3{font-size:clamp(22px,3.2vw,30px);letter-spacing:-.03em;line-height:1.15;margin-top:12px}
.hit p{color:var(--muted);margin-top:6px;max-width:38em}
.hit-act{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin-top:18px}
.hit-act span{color:var(--muted);font-size:14px}
.fresh{font-size:16px;letter-spacing:-.01em;color:var(--muted);font-weight:600;margin:0 0 10px 6px}
.panel{border-radius:28px;overflow:hidden}
.tabs{display:flex;gap:2px;padding:8px 10px 0;box-shadow:0 1px 0 var(--hair);align-items:flex-end}
.tabs [role=tab]{font:inherit;font-size:14px;font-weight:600;color:var(--muted);background:none;border:0;border-radius:12px 12px 0 0;padding:8px 14px;min-height:42px;cursor:pointer;box-shadow:none}
.tabs [role=tab]:hover{background:none;color:var(--ink);filter:none}
.tabs [role=tab][aria-selected=true]{color:var(--accent);box-shadow:inset 0 -2px 0 var(--accent)}
.tabs .sp{flex:1}
.tabs .cp{margin:0 4px 6px 0;padding:6px 18px;min-height:36px;font-size:14px;color:#fff}
.how{padding:12px 22px 0;color:var(--muted);font-size:14px}
pre{white-space:pre-wrap;word-break:break-word;font-size:14px;line-height:1.6;padding:10px 22px 22px;max-height:420px;overflow:auto;color:var(--ink)}
.strip{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px 16px;margin-top:20px;counter-reset:s}
.strip li{counter-increment:s;font-size:15px;color:var(--ink);line-height:1.35}
.strip li:before{content:counter(s);display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:12px;color:var(--accent);font-weight:600;margin-bottom:3px}
.strip li span{color:var(--muted)}
/* film: full bleed, no frame, edges melt into the page */
#film{max-width:none;padding:8px 0 clamp(8px,2vw,24px)}
.reel{position:relative;max-width:1680px;margin:0 auto;aspect-ratio:2/1}
.reel video{display:block;width:100%;height:100%;object-fit:cover;background:#F3F3F5;border:0;border-radius:0;box-shadow:none;outline:0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 15%,#000 85%,transparent),linear-gradient(180deg,transparent,#000 17%,#000 83%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent,#000 15%,#000 85%,transparent),linear-gradient(180deg,transparent,#000 17%,#000 83%,transparent);mask-composite:intersect;mix-blend-mode:multiply}
.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}
.ctl button{min-height:36px;padding:4px 16px;font-size:13px;background:var(--gl);color:var(--ink);box-shadow:var(--edge),0 6px 18px -6px rgba(30,50,110,.25)}
.dl{text-align:center;font-size:13px;color:var(--muted);margin-top:2px}
/* steps */
.rrp{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(20px,3.5vw,34px);margin-top:26px}
.rrp figure{position:relative;border-radius:22px;overflow:hidden;aspect-ratio:16/10;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.5);box-shadow:var(--edge),var(--lift)}
.rrp img{width:100%;height:100%;object-fit:contain;display:block}
.bdg{position:absolute;right:12px;top:12px;width:42px;height:42px;border-radius:50%;display:grid;place-items:center;animation:bob 6.5s ease-in-out infinite;--r:8deg}
.bdg svg{width:22px;height:22px}
.rrp h3{font-size:24px;letter-spacing:-.03em;margin-top:14px}
.rrp p{color:var(--muted);font-size:15px;margin-top:4px}
/* watch */
.watch{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.watch a{display:inline-block;text-decoration:none;color:var(--ink);border-radius:20px;padding:12px 18px;font-weight:600;transition:transform .3s var(--ease),color .2s}
.watch a[hidden]{display:none}
.watch a small{display:block;font-weight:400;color:var(--muted);font-size:13px}
.watch a:hover{color:var(--accent);transform:translateY(-3px)}
.cli{border-radius:22px;padding:16px 22px;margin-top:14px;font-size:14px;line-height:1.8;overflow-x:auto;white-space:pre}
.cli .p,.cli .c{color:var(--muted)}
.cli .p{user-select:none}
.cap{color:var(--muted);font-size:14px;margin-top:10px}
/* tools */
.tools{display:grid;gap:14px;margin-top:26px}
.tool{border-radius:30px;padding:clamp(20px,3vw,28px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:clamp(20px,3.5vw,32px);align-items:center}
.tool:nth-child(even) .txt{order:2}
.tool header{display:flex;align-items:center;gap:10px}
.tool img.lg2{width:38px;height:38px;border-radius:10px;display:block;box-shadow:0 4px 12px -2px rgba(0,0,0,.25)}
.tool h3{font-size:20px;letter-spacing:-.025em}
.tool .job{font-size:clamp(22px,2.8vw,28px);font-weight:700;letter-spacing:-.03em;line-height:1.15;margin-top:16px}
.tool p{color:var(--muted);font-size:15px;margin-top:6px}
.tool figure{border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 0 0 1px rgba(20,30,60,.06),0 10px 28px -10px rgba(30,50,110,.3)}
.tool figure img{display:block;width:100%;height:auto}
.tool figcaption{font-size:13px;color:var(--muted);padding:8px 14px;background:rgba(255,255,255,.8);box-shadow:0 -1px 0 var(--hair)}
.tool .more{display:inline-block;margin-top:12px;font-size:14px;font-weight:600}
.proof{margin-top:8px;color:var(--muted);max-width:36em}
#proof:has(.pending){display:none}
/* timeline: a race track, two stops a row, hairpin turns at the edges */
#built{max-width:1120px}
.tlw{position:relative;margin-top:30px}
.trk{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.trk .road{fill:none;stroke:var(--road);stroke-width:18;stroke-linecap:round;stroke-linejoin:round}
.trk .edge{fill:none;stroke:rgba(255,255,255,.7);stroke-width:20;stroke-linecap:round;stroke-linejoin:round}
.trk .mid{fill:none;stroke:#fff;stroke-width:2.5;stroke-dasharray:1 9;stroke-linecap:round}
.trk .done{fill:none;stroke:var(--accent);stroke-width:3.5;stroke-linecap:round;filter:drop-shadow(0 0 5px rgba(10,102,214,.55))}
.trk .pt{fill:#fff;stroke:var(--accent);stroke-width:3}
.trk .pt.next{fill:#fff;stroke:#9A9AA2}
.tl{list-style:none;padding:0 clamp(36px,6vw,72px);margin:0;position:relative;z-index:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row dense;column-gap:clamp(20px,3.5vw,44px);row-gap:clamp(24px,3.5vw,40px)}
.tl li:nth-child(4n+3){grid-column:2}
.tl li:nth-child(4n+4){grid-column:1}
.tl li{padding-top:30px;min-width:0}
.tl .when b{display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:13px;color:var(--ink);font-weight:600;margin-bottom:10px}
.tl .when span{display:block;color:var(--muted);font-size:14px;line-height:1.35;margin-bottom:10px}
.twitter-tweet{border-radius:20px;padding:16px 18px;font-size:15px;line-height:1.5;max-width:550px}
.twitter-tweet p{margin:0 0 .5em}
.twitter-tweet a{word-break:break-word}
.twitter-tweet-rendered{margin:0!important;border-radius:20px;box-shadow:var(--lift)}
.followx{font-weight:600;font-size:15px}
/* about */
.about{display:grid;grid-template-columns:190px minmax(0,1fr);gap:clamp(24px,4vw,44px);align-items:center}
.ph{position:relative}
.ph .im{border-radius:30px;aspect-ratio:4/5;overflow:hidden;background:var(--tint);box-shadow:var(--edge),var(--lift)}
.ph img{width:100%;height:100%;object-fit:cover;object-position:top;display:block}
.ph .stk{display:inline-flex;left:-14px;bottom:18px;--r:-6deg;font-size:12px}
.about p{color:var(--muted);margin-top:10px;max-width:34em}
.about h2+p{margin-top:0}
.links{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.links a{text-decoration:none;color:var(--ink);border-radius:99px;padding:6px 18px;font-weight:600;font-size:14px;min-height:38px;display:inline-flex;align-items:center;transition:color .2s,transform .3s var(--ease)}
.links a:hover{color:var(--accent);transform:translateY(-2px)}
footer{max-width:960px;margin:0 auto;padding:28px 24px 48px;color:var(--muted);font-size:13px;display:flex;flex-wrap:wrap;gap:8px 24px;justify-content:space-between;align-items:center}
footer .wm{font-size:14px}footer .lg{width:22px;height:22px}
footer nav{display:flex;flex-wrap:wrap;gap:8px 20px}
@media(max-width:860px){.tool{grid-template-columns:1fr}.tool:nth-child(even) .txt{order:0}.rrp{grid-template-columns:1fr}.rrp figure{aspect-ratio:16/9}.nl{display:none}}
@media(max-width:720px){section{padding-left:20px;padding-right:20px}.strip{grid-template-columns:1fr 1fr}body{font-size:16px}.box{flex-wrap:wrap;padding:8px 8px 8px 18px;border-radius:28px}.box input{flex:1 1 100%;font-size:17px}.box button{width:100%}.tabs{flex-wrap:wrap}.tabs .sp{display:none}.tabs .cp{margin:0 0 6px auto}.hit{padding:20px}.hit-act .btn{width:100%}
 .reel{aspect-ratio:16/9}.ctl{right:20px;bottom:6%}
 .tl{grid-template-columns:minmax(0,1fr);padding:0 0 0 40px}.tl li:nth-child(n){grid-column:auto}
 .about{grid-template-columns:1fr;gap:20px}.ph{max-width:190px}}
@media(prefers-reduced-motion:reduce){#hero>*,.icon,.stk,.bdg{animation:none}html.js .rv{opacity:1;transform:none;transition:none}html{scroll-behavior:auto}.stk .d{animation:none;stroke-dashoffset:0}}
@media(prefers-reduced-transparency:reduce){.gl,.hit,.panel,.tool,.cli,.watch a,.links a,.nav,.box,.chips button,.stk,.bdg,.twitter-tweet{-webkit-backdrop-filter:none;backdrop-filter:none;background:#fff}}

